mapper.select:
SELECT sequence_status_change_id, status_update_time, change_status, status_result_msg, task_response_id, ctrl_cmd_sequence_id, request_control_command_id FROM msa_sequence_status_change_record where 1=1
and sequence_status_change_id = #{sequenceStatusChangeId}
and ctrl_cmd_sequence_id = #{ctrlCmdSequenceId}
and request_control_command_id = #{requestControlCommandId}
order by sequence_status_change_id desc

